import { useState } from 'react';
import { Download, FileImage } from 'lucide-react';
import Notice from '../../components/ui/Notice';
import useApi from '../../hooks/useApi';
import { api, downloadFile } from '../../api/client';
import '../../components/dashboard/DashboardPage.scss';
import './ContestantPromotionalMaterialsPage.scss';

// Ready-made graphics generated by the backend with the contestant's name, category, photo and voting QR code.
export default function ContestantPromotionalMaterialsPage() {
  const { data, error } = useApi('/contestants/me/promo');
  const [busy, setBusy] = useState(null);
  const [message, setMessage] = useState(null);

  const download = async (m) => {
    setBusy(m.key);
    setMessage(null);
    try {
      await downloadFile(`/contestants/me/promo/materials/${m.key}`, `${m.key}.svg`);
      const id = data.voteUrl.split('contestant=')[1];
      api(`/contestants/${id}/share-events`, { method: 'POST', body: { type: 'share', channel: 'download' } }).catch(() => {});
      setMessage({ tone: 'success', text: `${m.name} downloaded.` });
    } catch (err) {
      setMessage({ tone: 'error', text: err.message });
    } finally {
      setBusy(null);
    }
  };

  return (
    <div className="dash-page">
      <div className="dash-page__header">
        <div>
          <h1 className="dash-page__title">Promotional Materials</h1>
          <p className="dash-page__subtitle">
            Ready-made graphics with your name, photo and voting QR code. Files are SVG: they open in any browser and print sharp at any size.
          </p>
        </div>
      </div>

      <Notice tone="error">{error?.message}</Notice>
      <Notice tone={message?.tone}>{message?.text}</Notice>

      <div className="promo-materials__grid">
        {(data?.materials ?? []).map((m) => (
          <div className="promo-materials__card" key={m.key}>
            <div className="promo-materials__preview" style={{ aspectRatio: `${m.width} / ${m.height}`, maxHeight: 140 }}>
              <FileImage size={26} />
            </div>
            <p className="promo-materials__name">{m.name}</p>
            <p className="promo-materials__type">
              {m.type} · {m.format}
            </p>
            <button type="button" className="btn btn--outline" disabled={busy === m.key} onClick={() => download(m)}>
              <Download size={14} /> {busy === m.key ? 'Preparing…' : 'Download'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
